scripts.floor_division_sum:
def solve(inputs: dict) -> float:
    A = inputs['A']
    B = inputs['B']

    # Compute sum of floor divisions
    total = sum(a // b for a, b in zip(A, B))

    return float(total)

scripts.factorial_mod:
def solve(inputs: dict) -> float:
    N = inputs['N']
    MOD = inputs['MOD']

    # Compute factorial modulo MOD
    result = 1
    for i in range(1, N + 1):
        result = (result * i) % MOD
        print(f"{i}! mod {MOD} = {result}")

    return float(result)

